CREATE FUNCTION public.guc_saved_path() RETURNS text LANGUAGE sql SET search_path FROM CURRENT AS $$SELECT current_setting('search_path')$$;
SELECT set_config('search_path','public',false);
SELECT public.guc_saved_path(),current_setting('search_path');
BEGIN;
SELECT set_config('search_path','GUC_RAW,public',false);
SAVEPOINT saved_path;
SELECT set_config('search_path','  "Guc Space" , public  ',true);
ROLLBACK TO saved_path;
SELECT current_setting('search_path');
ROLLBACK;
SELECT current_setting('search_path');
DROP FUNCTION public.guc_saved_path();
DROP TABLE guc_raw.guc_visible;
DROP TABLE "Guc Space".guc_visible;
DROP SCHEMA guc_raw;
DROP SCHEMA "Guc Space";
RESET search_path;
